 /* Section Styles */

 .section { padding: 40px 20px; max-width: 1100px; margin: 0 auto; }

 .section:first-of-type { padding-top: 20px; }

 .section-title {

 font-size: 2em;

 letter-spacing: 8px;

 text-align: center;

 margin-bottom: 30px;

 color: #c9a961;

 font-family: 'Times New Roman', serif;

 }



 /* Timeline */

 .timeline { position: relative; padding-left: 40px; }

 .timeline-item {

 display: flex;
 align-items: flex-start;
 gap: 20px;
 padding: 15px;
 margin-bottom: 10px;
 background: #1a1a1a;
 border-radius: 8px;
 cursor: pointer;
 transition: all 0.3s ease;
 }

 .timeline-item:hover {

 background: #222;
 transform: translateX(5px);
 }

 .timeline-item.expanded {

 background: #151515;
 border-left: 3px solid #c9a961;
 border-radius: 8px;
 padding: 10px;
 }

 /* Paragraph spacing in expanded content - match bot-message */
 .timeline-item.expanded p,
 .trail-point.expanded p,
 .martin-point.expanded p {
   margin-bottom: 12px;
   line-height: 1.7;
   color: #ccc;
 }

 .timeline-item:hover .timeline-title {

 color: #c9a961;

 }

 .timeline-title a {

 color: inherit;

 text-decoration: none;

 transition: color 0.3s ease;

 }

 .timeline-link-icon {

 position: absolute;

 right: 10px;

 top: 50%;

 transform: translateY(-50%);

 color: #c9a961;

 font-size: 0.9em;

 opacity: 0;

 transition: opacity 0.3s ease;

 }

 .timeline-item:hover .timeline-link-icon {

 opacity: 1;

 }

 .timeline-item::before {

 display: none;

 }

 border-radius: 50%;

 border: 3px solid #0a0a0a;

 transition: all 0.3s ease;

 }

 .timeline-item:hover::before {

 transform: scale(1.3);

 box-shadow: 0 0 10px rgba(201, 169, 97, 0.6);

 }

 .timeline-item:hover .timeline-title {

 color: #c9a961;

 }

 .timeline-item.expanded::before {

 transform: scale(1.3);

 box-shadow: 0 0 10px rgba(201, 169, 97, 0.8);

 }

 .timeline-date {

 font-size: 0.9em;

 color: #c9a961;

 letter-spacing: 2px;

 margin-bottom: 8px;

 font-weight: bold;

 }

 .timeline-title {

 font-size: 1em;

 margin-bottom: 8px;

 color: #fff;

 transition: color 0.3s ease;

 }

 .timeline-desc {

 color: #aaa;

 line-height: 1.7;

 }

